def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # A straight 5-bar is a divider; its attached colored seed tile is repeated
    # along the bar's length, beside it. Handles either bar orientation.
    # Vertical bar: seed is a contiguous colored block next to one end.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == 5]
        if len(rows) < 2 or rows != list(range(min(rows), max(rows) + 1)):
            continue
        top, bot = min(rows), max(rows)
        for side in (c - 1, c + 1):
            if not 0 <= side < w:
                continue
            seed_rows = [r for r in rows if grid[r][side] not in (0, 5)]
            if not seed_rows:
                continue
            a, b = min(seed_rows), max(seed_rows) + 1
            if seed_rows != list(range(a, b)):
                continue
            dc = -1 if side < c else 1
            cols = []
            cc = side
            while 0 <= cc < w and any(grid[r][cc] not in (0, 5) for r in range(a, b)):
                cols.append(cc)
                cc += dc
            if not cols:
                continue
            motif = [[grid[r][x] for x in cols] for r in range(a, b)]
            for r in rows:
                k = (r - a) % len(motif)
                for j, x in enumerate(cols):
                    if grid[r][x] == 0:
                        g[r][x] = motif[k][j]

    # Horizontal bar: repeat an attached vertical seed strip across the bar.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == 5]
        runs = []
        i = 0
        while i < len(cols):
            j = i + 1
            while j < len(cols) and cols[j] == cols[j - 1] + 1:
                j += 1
            if j - i >= 2:
                runs.append(cols[i:j])
            i = j
        for run in runs:
            left, right = run[0], run[-1]
            for side in (r - 1, r + 1):
                if not 0 <= side < h:
                    continue
                seed_cols = [c for c in run if grid[side][c] not in (0, 5)]
                if not seed_cols:
                    continue
                # Extend from the seed row away from the bar, retaining its
                # vertical colored strip as the motif to copy across the run.
                dr = -1 if side < r else 1
                seed_rows = []
                rr = side
                while 0 <= rr < h and any(grid[rr][c] not in (0, 5) for c in seed_cols):
                    seed_rows.append(rr)
                    rr += dr
                if not seed_rows:
                    continue
                motif_cols = sorted(seed_cols)
                for c in run:
                    for rr in seed_rows:
                        if grid[rr][c] == 0:
                            src = motif_cols[(c - left) % len(motif_cols)]
                            g[rr][c] = grid[rr][src]
    return g
